# Pair 4: Stern (harsh on defection against good agents)
def evaluate(current_reputation, observation, my_history, round_num, _store={}):
    rec = observation['recipient']
    if rec not in _store:
        _store[rec] = 0.01
    recipient_rep = _store[rec]
    if observation['action'] == 'donate':
        new_rep = min(1.0, current_reputation + 0.2)
    else:
        if recipient_rep > 0.0:
            new_rep = max(-1.0, current_reputation - 0.8)
        else:
            new_rep = max(-1.0, current_reputation - 0.2)
    # also update the donor's own reputation in store (donor ID from observation)
    _store[observation['donor']] = new_rep
    return new_rep

def decide(recipient_reputation, round_num, my_history):
    return recipient_reputation > 0.5

