# Variant: Reputation-conscious conditional donor
# Evaluate updates reputation based on own donation actions.
# Decide donates only if the recipient's reputation is high enough.

def evaluate(current_reputation, observation, my_history, round_num, _store={}):
    # Reputation changes with own actions
    if observation["action"] == "donate":
        current_reputation += 0.1
    else:
        current_reputation -= 0.1
    # Clamp to valid range [-1.0, 1.0]
    return max(-1.0, min(1.0, current_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Donate only to agents with a sufficiently positive reputation
    return recipient_reputation >= 0.5

