def decide(recipient_reputation, round_num, my_history):
    # If we have at least one past interaction and the last time we were the recipient
    # the other agent donated to us, reciprocate by donating now.
    if my_history and my_history[-1]['partner_action'] == 'donate':
        return True
    # Otherwise donate only if the recipient's reputation is above a moderate threshold.
    if recipient_reputation > 0.6:
        return True
    return False
